// Take-On-Me-Comic (a-ha): Bleistift-Rotoskopie — Sobel-Kantenzug,
// Papier/Tinte, Schraffur in dunklen Flaechen. Die Schraffur-Phase zittert
// alle paar Frames (Rotoskopie-Wackeln), der Beat gibt einen Extra-Ruck.
float lum(vec2 p) { return dot(texture(uTex, p).rgb, vec3(0.299, 0.587, 0.114)); }
vec4 farbe(vec2 uv, vec4 src)
{
    vec2 px = 1.0 / uResolution;
    float tl = lum(uv + px * vec2(-1.0,  1.0));
    float tt = lum(uv + px * vec2( 0.0,  1.0));
    float tr = lum(uv + px * vec2( 1.0,  1.0));
    float ll = lum(uv + px * vec2(-1.0,  0.0));
    float rr = lum(uv + px * vec2( 1.0,  0.0));
    float bl = lum(uv + px * vec2(-1.0, -1.0));
    float bb = lum(uv + px * vec2( 0.0, -1.0));
    float br = lum(uv + px * vec2( 1.0, -1.0));
    float gx = tr + 2.0 * rr + br - tl - 2.0 * ll - bl;
    float gy = tl + 2.0 * tt + tr - bl - 2.0 * bb - br;
    float kante = smoothstep(0.18, 0.45, length(vec2(gx, gy)));
    float hell = dot(src.rgb, vec3(0.299, 0.587, 0.114));
    // Schraffur 45 Grad; Phase springt alle 3 Frames + Beat-Ruck
    float phase = fract(sin(floor(float(uFrame) / 3.0) * 12.9898) * 43758.5453);
    phase += beat * 0.5;
    float welle = sin((uv.x + uv.y) * uResolution.y * 0.35 + phase * 6.2832);
    float linie = smoothstep(0.15, -0.15, welle);
    float dunkel = smoothstep(0.60, 0.15, hell);
    vec3 papier = vec3(0.94, 0.92, 0.87);
    vec3 tinte = vec3(0.10, 0.09, 0.12);
    float deckung = clamp(kante + linie * dunkel * 0.75, 0.0, 1.0);
    return vec4(mix(papier, tinte, deckung), 1.0);
}
